// Jellyfish that drifts up and down

import { step } from "../world/movement.js";
import { bounce } from "../world/bounds.js";

// Colours
const BODY_COLOR = "rgba(200,100,255,0.6)";
const TENTACLE_COLOR = "rgba(150,80,200,0.4)";

export const count = 3;

export function spawn(world) {
  // Start near the bottom middle
  const x = 0;
  const y = world.bounds.bottom - 20;
  // No initial velocity; will be set in update
  return { x, y, vx: 0, vy: 0, kind: "jellyfish" };
}

export function update(creature, world) {
  // Oscillate vertically using a sine wave based on age
  const amplitude = 0.4; // speed units
  creature.vy = Math.sin(creature.age * 0.1) * amplitude;
  // Apply movement
  step(creature);
  // Keep inside bounds vertically, bounce at top/bottom
  bounce(creature);
}

export function draw(creature, pen, world) {
  const { x, y } = creature;
  pen.save();
  pen.translate(x, y);
  // Body
  pen.fill(BODY_COLOR);
  pen.ellipse(0, 0, 20, 30);
  // Tentacles
  pen.stroke(TENTACLE_COLOR);
  pen.lineWidth = 2;
  for (let i = -8; i <= 8; i += 4) {
    pen.line(0, 15, i, 30);
  }
  pen.restore();
}

