// No movement import needed

const BODY = "purple";
const ARM = "pink";

export function spawn() {
  // start at center, no velocity, angle 0
  return { x: 0, y: 0, vx: 0, vy: 0, angle: 0 };
}

export function update(starfish, world) {
  // slowly rotate
  starfish.angle += 0.01;
  // keep angle within 0-2π for neatness
  if (starfish.angle > Math.PI * 2) starfish.angle -= Math.PI * 2;
}

export function draw(starfish, pen) {
  // rotate drawing context
  pen.turn(starfish.angle);
  // draw a simple starfish shape: five arms
  pen.fill(BODY);
  // central disc
  pen.ellipse(0, 0, 16, 16);
  pen.fill(ARM);
  // arms as triangles
  for (let i = 0; i < 5; i++) {
    pen.triangle(-4, -30, 4, -30, 0, -10);
    pen.turn(Math.PI * 2 / 5);
  }
}

export const count = 3;

