// Sea urchin that waves its spines
import { FLOOR_Y } from "../world/bounds.js";

const BODY = "sand";
const SPIKE = "purple";

export function spawn(world) {
  // positioned on the sand surface
  return { y: FLOOR_Y - 4, sway: 0 };
}

export function update(urchin, world) {
  // sway oscillates over time to animate spines
  urchin.sway = Math.sin(world.tick / 20) * 5;
}

export function draw(urchin, pen, world) {
  // draw the body
  pen.fill(BODY);
  pen.circle(0, 0, 8);
  // draw spines radiating outward, animated by sway
  pen.stroke(SPIKE, 2);
  for (let i = 0; i < 12; i++) {
    const angle = (i / 12) * Math.PI * 2 + urchin.sway * Math.PI / 180;
    const x = Math.cos(angle) * 8;
    const y = Math.sin(angle) * 8;
    const x2 = Math.cos(angle) * 14;
    const y2 = Math.sin(angle) * 14;
    pen.line(x, y, x2, y2);
  }
}

