import { ENERGY_MAX } from "../world/energy.js";
import { step, steer, glide } from "../world/movement.js";
import { wrap } from "../world/bounds.js";

// Simple manta ray that glides in wide slow circles.
const BODY = "gray";
const WING = "darkgray";

export function spawn(world) {
  // start with zero velocity; movement will be driven by steering toward a rotating target.
  return { vx: 0, vy: 0, angle: 0, energy: ENERGY_MAX };
}

export function update(manta, world) {
  // Increase the internal angle to create a rotating target point.
  manta.angle += 0.01; // slow rotation
  const radius = 120; // radius of the circle path
  const targetX = manta.x + radius * Math.cos(manta.angle);
  const targetY = manta.y + radius * Math.sin(manta.angle);
  // Steer gently toward the rotating target.
  steer(manta, targetX, targetY, 0.02);
  // Glide slowly.
  glide(manta, 0.99);
  step(manta);
  wrap(manta);
}

export function draw(manta, pen) {
  // Draw a simple manta shape: a flat body with wide wings.
  pen.fill(WING);
  // left wing
  pen.poly([-30, 0, -60, -20, -80, 0, -60, 20]);
  // right wing (mirrored)
  pen.poly([30, 0, 60, -20, 80, 0, 60, 20]);
  pen.fill(BODY);
  pen.ellipse(0, 0, 40, 12);
}

