export function spawn() {
  // tiny fish, low speed
  return { vx: 1, vy: 0, energy: ENERGY_MAX };
}

export function update(fish, world) {
  // Find other bluefish to stay together
  const others = world.creatures.filter(c => c.kind === "bluefish" && c.id !== fish.id);
  if (others.length) {
    let avgX = 0, avgY = 0;
    for (const o of others) {
      avgX += o.x;
      avgY += o.y;
    }
    avgX /= others.length;
    avgY /= others.length;
    steer(fish, avgX, avgY, 0.2);
  } else {
    // wander
    steer(fish, fish.x + (fish.vx < 0 ? -50 : 50), fish.y, 0.05);
  }
  glide(fish, 0.95);
  step(fish);
  wrap(fish);
}

export function draw(fish, pen) {
  if (fish.vx < 0) pen.flip();
  pen.fill(FIN);
  pen.poly([-7, 0, -14, -5, -14, 5]);
  pen.fill(BODY);
  pen.ellipse(0, 0, 10, 5);
  pen.fill("black");
  pen.circle(5, -2, 1);
}

