import { ENERGY_MAX, isHungry } from "../world/energy.js";
import { nearestFood } from "../world/food.js";
import { step, steer, glide } from "../world/movement.js";
import { wrap } from "../world/bounds.js";

const BODY = "green";
const SPIKE = "yellow";
const PUFF_COLOR = "lightgreen";
const PUFF_RADIUS = 30; // when puffed
const NORMAL_RADIUS = 15;
const PUFF_DISTANCE = 40; // distance to another creature to puff up

export function spawn() {
  return { vx: 1, energy: ENERGY_MAX, puffed: false };
}

export function update(puffer, world) {
  // Find nearest other creature
  let close = false;
  for (const other of world.creatures) {
    if (other.id === puffer.id) continue;
    const dx = other.x - puffer.x;
    const dy = other.y - puffer.y;
    if (dx * dx + dy * dy < PUFF_DISTANCE * PUFF_DISTANCE) {
      close = true;
      break;
    }
  }
  puffer.puffed = close;

  // Simple wandering / food seeking similar to fish
  const food = isHungry(puffer) ? nearestFood(puffer, world) : null;
  if (food) steer(puffer, food.x, food.y, 0.2);
  else steer(puffer, puffer.x + (puffer.vx < 0 ? -100 : 100), puffer.y, 0.05);
  glide(puffer, 0.98);
  step(puffer);
  wrap(puffer);
}

export function draw(puffer, pen) {
  // Body
  pen.fill(BODY);
  const radius = puffer.puffed ? PUFF_RADIUS : NORMAL_RADIUS;
  pen.ellipse(0, 0, radius * 2, radius * 1.2);
  // Spikes when puffed
  if (puffer.puffed) {
    pen.fill(SPIKE);
    pen.poly([
      -radius, 0,
      -radius - 5, -5,
      -radius, -10,
      -radius - 5, -15,
      -radius, -20,
    ]);
    pen.poly([
      radius, 0,
      radius + 5, -5,
      radius, -10,
      radius + 5, -15,
      radius, -20,
    ]);
  }
}

export const count = 3;

