// Energy rules for creatures.
// Energy is measured in points from 0 (empty) to ENERGY_MAX (full).
export const ENERGY_MAX = 100;

// Cost of one tick of ordinary living.
export const LIVING_COST = ENERGY_MAX / 3600;

// Threshold below which a creature is considered hungry.
export const HUNGRY_BELOW = ENERGY_MAX / 2;

// Number of ticks an empty creature rests before waking up full.
export const REST_TICKS = 300;

// Does the creature participate in the energy system?
// Returns true when the creature's `energy` property is a number.
export function usesEnergy(creature) {
  return typeof creature.energy === "number";
}

// Remove energy from a creature.
// `amount` is expressed in the same units as ENERGY_MAX.
export function drain(creature, amount) {
  creature.energy = Math.max(0, creature.energy - amount);
}

// Add energy to a creature.
// `amount` is expressed in the same units as ENERGY_MAX.
export function feed(creature, amount) {
  creature.energy = Math.min(ENERGY_MAX, creature.energy + amount);
}

// Check if a creature is hungry (energy below HUNGRY_BELOW).
export function isHungry(creature) {
  return creature.energy < HUNGRY_BELOW;
}

// Check if a creature is currently resting (resting > 0).
export function isResting(creature) {
  return creature.resting > 0;
}

// Process one tick of life for a creature that uses energy.
// Handles resting, energy drain, and transition to resting state.
export function liveOneTick(creature) {
  if (creature.resting > 0) {
    creature.resting -= 1;
    if (creature.resting === 0) creature.energy = ENERGY_MAX;
    return;
  }
  drain(creature, LIVING_COST);
  if (creature.energy <= 0) creature.resting = REST_TICKS;
}

